function makeScene(){c.fillStyle='#020509';c.fillRect(0,0,640,360);if(scene==='road'&&loaded)c.drawImage(road,0,0,640,360);else if(scene==='reading'){c.fillStyle='#d6d9d5';c.fillRect(0,0,640,360);c.fillStyle='#222';c.font='26px Georgia';c.fillText('Clear at the chosen distance. ',32,53);c.font='22px Georgia';c.fillText('Glasses can add the required focus. ',32,99);for(let j=0;j<4;j++){const co=[.85,.35,.12,.04][j],g=Math.round(214*(1-co));c.fillStyle=`rgb(${g},${g},${g})`;c.font='23px sans-serif';c.fillText('C E F P T',32+j*150,174);c.font='15px sans-serif';c.fillStyle='#444';c.fillText(['High','Medium','Low','Very low'][j],32+j*150,207);for(let x=0;x<125;x++){const v=Math.round(160*(1+co*Math.sin(x*.45)));c.fillStyle=`rgb(${v},${v},${v})`;c.fillRect(32+j*150+x,243,1,68);}}}else{c.fillStyle='white';c.fillRect(320,180,1,1);}return c.getImageData(0,0,640,360).data;}
function pump(){if(busy||!queue.length)return;busy=true;worker.postMessage(queue.shift());}
function render(t){sync();if(scene==='road'&&!loaded){$('status').textContent='Loading night scene…';return Promise.resolve({loading:true});}const id=++serial;latest[t]=id;$('status').textContent='Calculating…';const p=new Promise((resolve,reject)=>pending.set(id,{resolve,reject,target:t,scene,snapshot:{...configs[t]}}));const kept=[];for(const j of queue){if(j.target===t){pending.get(j.id)?.resolve({superseded:true});pending.delete(j.id);}else kept.push(j);}queue=kept;queue.push({id,target:t,sceneKey:scene,state:{...configs[t],scene:scene==='reading'||example==='near'?'reading':scene==='road'?'road':'star'},input:makeScene(),width:640,height:360});pump();return p;}
function renderBoth(){return Promise.all([render('a'),render('b')]).catch(()=>{});}
function pointImage(data){const image=new ImageData(640,360);for(let y=0;y<360;y++)for(let x=0;x<640;x++){const ux=128+(x-320)/10,uy=128+(y-180)/10,px=Math.floor(ux),py=Math.floor(uy),tx=ux-px,ty=uy-py;let value=0;if(px>=0&&px<255&&py>=0&&py<255)value=data.psf[py*256+px]*(1-tx)*(1-ty)+data.psf[py*256+px+1]*tx*(1-ty)+data.psf[(py+1)*256+px]*(1-tx)*ty+data.psf[(py+1)*256+px+1]*tx*ty;const v=Math.max(0,Math.min(1,(Math.log10(Math.max(value,1e-12))+6)/6)),i=(y*640+x)*4;image.data[i]=Math.round(225*v);image.data[i+1]=Math.round(250*v);image.data[i+2]=Math.round(245*v);image.data[i+3]=255;}return image;}
worker.onmessage=({data:d})=>{busy=false;const p=pending.get(d.id);pending.delete(d.id);if(p){if(d.error){$('status').textContent='Model unavailable';p.reject(new Error(d.error));}else{const t=p.target;if(latest[t]===d.id){results[t]=d;const img=p.scene==='psf'?pointImage(d):new ImageData(d.output,640,360);$('canvas-'+t).getContext('2d').putImageData(img,0,0);if(edit===t)graphs(d);}p.resolve({scenario:t,settings:p.snapshot,residualCylinder:residualCylinder(p.snapshot)});}}pump();if(!busy&&!queue.length)$('status').textContent='';};worker.onerror=()=>{$('status').textContent='Optical model unavailable';for(const p of pending.values())p.reject(new Error('Worker error'));pending.clear();queue=[];busy=false;};
function graphs(d){const g=$('psf').getContext('2d'),img=g.createImageData(256,256);for(let i=0;i<d.psf.length;i++){const v=Math.max(0,Math.min(1,(Math.log10(Math.max(d.psf[i],1e-12))+6)/6));img.data[i*4]=225*v;img.data[i*4+1]=250*v;img.data[i*4+2]=245*v;img.data[i*4+3]=255;}g.putImageData(img,0,0);$('psf-note').textContent='Central '+(d.field*60).toFixed(1)+' arcminute crop; convolution kernel retains  '+(d.retained*100).toFixed(2)+'% of PSF energy. ';const m=$('mtf').getContext('2d');m.fillStyle='#0b141c';m.fillRect(0,0,520,280);m.font='12px sans-serif';for(let j=0;j<=4;j++){const y=22+j*50;m.strokeStyle='#293b47';m.beginPath();m.moveTo(48,y);m.lineTo(498,y);m.stroke();m.fillStyle='#b4c2cd';m.textAlign='right';m.fillText((1-j/4).toFixed(2),40,y+4);m.textAlign='center';m.fillText(String(j*10),48+j*112.5,242);}m.fillText('Spatial frequency · cycles/degree',273,268);for(const [a,color,dash]of [[d.ideal,'#708390',[4,4]],[d.horizontal,'#8de3ce',[]],[d.vertical,'#efb88a',[5,3]]]){m.strokeStyle=color;m.lineWidth=2;m.setLineDash(dash);m.beginPath();a.forEach((v,i)=>i?m.lineTo(48+450*i/40,22+200*(1-v)):m.moveTo(48,22+200*(1-v)));m.stroke();}m.setLineDash([]);}
function applyExample(v){example=v;configs={a:{...base,glasses:true},b:{...base,toric:true}};if(v==='aspheric'){configs.a={...base,astig:0,aspheric:false};configs.b={...base,astig:0,aspheric:true};}if(v==='near'){configs.a={...base,astig:0,distance:0};configs.b={...base,astig:0,distance:2.5};scene='reading';}setView('split');renderBoth();}
function guide(){const e=evidence[lens];$('guide-title').textContent=e.title;$('guide-summary').textContent=e.summary;for(const key of ['pros','cons'])$(key).replaceChildren(...e[key].map(([text,source])=>{const li=document.createElement('li');li.append(document.createTextNode(text+' '));const a=document.createElement('a');a.href=sources[source];a.target='_blank';a.rel='noopener';a.textContent='Source ↗';li.append(a);return li;}));document.querySelectorAll('[data-lens]').forEach(e=>e.setAttribute('aria-pressed',String(e.dataset.lens===lens)));$('guide-note').textContent=lens==='enhanced'?'Trial scope: Eyhance, Impress and NSP-3 compared with Tecnis monofocal; 172 patients and two months of follow-up. No significant difference does not establish equivalence or exclude rare adverse events. ':'Lens category alone cannot predict personal results. This app has not been reviewed by an ophthalmologist. ';}
