$('guide-open').onclick=()=>{guide();open('guide-dialog');};$('science-open').onclick=()=>{sync();open('science-dialog');};$('settings-open').onclick=()=>open('settings-dialog');$('methods-open').onclick=()=>open('methods-dialog');fetch('method-content.html').then(r=>{if(!r.ok)throw Error();return r.text();}).then(h=>{$('method-content').innerHTML=h;}).catch(()=>{$('method-content').innerHTML='<p>Please read the<a href="VALIDATION.md">validation record and model assumptions</a>.</p>';});$('fullscreen').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen?.();else document.documentElement.requestFullscreen?.().catch(()=>{});};
