let step=0,answers=[];const questions=[{q:'What matters more to you?',a:[['contrast','Clear night-time contrast'],['freedom','Less reliance on glasses']],note:'Organise your priorities for a discussion with your surgeon. '},{q:'Are you comfortable with reading glasses?',a:[['yes','Yes, I am used to them'],['no','I would prefer to use them less']],note:'This preference helps frame the lens trade-offs. '},{q:'Has the surgeon confirmed corneal astigmatism?',a:[['yes','Yes'],['no','No'],['unknown','Not sure yet']],note:'Astigmatism requires eye measurements. '}];function decision(){const done=step===3;$('step-label').textContent=done?'Prepare to discuss with your surgeon':'Your priorities · '+(step+1)+' / 3';$('decision-back').hidden=step===0;if(!done){const q=questions[step];$('decision-question').textContent=q.q;$('decision-note').textContent=q.note;$('decision-options').replaceChildren(...q.a.map(([value,label])=>{const b=document.createElement('button');b.textContent=label;if(value==='unknown')b.className='small-choice';b.onclick=()=>{answers[step]=value;step++;decision();};return b;}));}else{const contrast=answers[0]==='contrast',glasses=answers[1]==='yes';$('decision-question').textContent=contrast&&glasses?'Ask about distance-targeted Monofocal. ':contrast?'Discuss contrast first, then reliance on glasses. ':'Discuss the benefits and costs of using glasses less. ';$('decision-note').textContent=(contrast&&glasses?'This is a starting point for discussing your priorities, not a prescription. ':contrast?'Ask how much intermediate vision Enhanced monofocal adds. ':'Ask about EDOF and Multifocal, including halos and dim-light contrast. ')+(answers[2]==='unknown'?'Astigmatism correction requires examination results. ':answers[2]==='yes'?'Ask whether Toric would be worthwhile. ':'Check whether astigmatism needs correction. ');const b=document.createElement('button');b.textContent='Explore trade-offs';b.onclick=()=>{lens=contrast?(glasses?'mono':'enhanced'):'edof';guide();open('guide-dialog');};const r=document.createElement('button');r.textContent='Start again';r.className='small-choice';r.onclick=()=>{step=0;answers=[];decision();};$('decision-options').replaceChildren(b,r);}}$('decision-back').onclick=()=>{step=Math.max(0,step-1);answers=answers.slice(0,step);decision();};
function validate(input){if(!input||typeof input!=='object'||Array.isArray(input))throw Error('Expected settings');const allowed=new Set(['target','scene','view','aspheric','toric','glasses','astig','rotation','pupil','decenter']);for(const k of Object.keys(input))if(!allowed.has(k))throw Error('Unknown field: '+k);for(const [k,list]of Object.entries({target:['a','b'],scene:['psf','road','reading'],view:['a','b','split']}))if(k in input&&!list.includes(input[k]))throw Error('Invalid '+k);for(const k of ['aspheric','toric','glasses'])if(k in input&&typeof input[k]!=='boolean')throw Error('Invalid '+k);for(const[k,[min,max]]of Object.entries({astig:[0,2.5],rotation:[0,30],pupil:[2,6],decenter:[0,.6]}))if(k in input&&(typeof input[k]!=='number'||!Number.isFinite(input[k])||input[k]<min||input[k]>max))throw Error('Invalid '+k);return input;}
if(document.modelContext?.registerTool){const ac=new AbortController();window.addEventListener('pagehide',()=>ac.abort(),{once:true});try{Promise.resolve(document.modelContext.registerTool({name:'configure_lens_comparison',description:'Configure one A/B single-focus optical example. Does not model a commercial implant or record medical data.',inputSchema:{type:'object',properties:{target:{type:'string',enum:['a','b']},scene:{type:'string',enum:['psf','road','reading']},view:{type:'string',enum:['a','b','split']},aspheric:{type:'boolean'},toric:{type:'boolean'},glasses:{type:'boolean'},astig:{type:'number',minimum:0,maximum:2.5},rotation:{type:'number',minimum:0,maximum:30},pupil:{type:'number',minimum:2,maximum:6},decenter:{type:'number',minimum:0,maximum:.6}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:async raw=>{const i=validate(raw);edit=i.target||edit;if(i.view)setView(i.view);const changedScene=i.scene&&i.scene!==scene;if(i.scene){scene=i.scene;if(example==='near'&&scene!=='reading'){example='cylinder';configs.a.distance=configs.b.distance=0;}}for(const k of ['aspheric','toric','glasses','astig','rotation','pupil','decenter'])if(k in i)configs[edit][k]=i[k];if(changedScene)return await renderBoth();return await render(edit);}},{signal:ac.signal})).catch(()=>{});}catch{}}
